#include "ApprovalModel.h"
#include <QJsonDocument>
#include <QDateTime>
ApprovalModel::ApprovalModel(QObject*parent):QAbstractListModel(parent),document_({},this){expiry_.setInterval(1000);connect(&expiry_,&QTimer::timeout,this,[this]{emit changed();});connect(&document_,&ApprovalDocument::changed,this,[this]{details_=document_.complete()&&document_.verified()?document_.pageAt(0):QString();deadline_.clear();if(document_.complete()&&document_.verified()&&selected().value("tool")=="shell_run"&&document_.byteCount()<=196608){QByteArray raw;for(int i=0;i<document_.pageCount();++i)raw+=document_.pageAt(i).toUtf8();const auto envelope=QJsonDocument::fromJson(raw).object();const auto request=envelope.value("request").isObject()&&envelope.value("operationId")==selected_&&envelope.value("fingerprint")==fingerprint_?envelope.value("request").toObject():envelope;const auto args=request.value("args").toObject();if(request.value("tool")=="shell_run"&&args.contains("timeoutMs")){const auto timeout=args.value("timeoutMs");if(timeout.isNull())deadline_="No time limit";else if(timeout.isDouble())deadline_=QString("Time limit: %1 seconds of active time").arg(timeout.toDouble()/1000.0,0,'g',15);}}emit detailsChanged();emit changed();});}
QHash<int,QByteArray> ApprovalModel::roleNames()const{return{{OperationId,"operationId"},{ToolName,"toolName"},{Risk,"risk"},{Status,"status"},{Summary,"summary"},{Output,"output"},{Truncated,"truncated"},{Targets,"targets"},{Fingerprint,"fingerprint"},{Expires,"expiresAt"}};}
QVariant ApprovalModel::data(const QModelIndex&i,int role)const{if(!i.isValid()||i.row()<0||i.row()>=rows_.size())return {};const auto row=rows_[i.row()].toObject();const QHash<int,QString> keys{{OperationId,"id"},{ToolName,"tool"},{Risk,"risk"},{Status,"status"},{Summary,"summary"},{Output,"output"},{Truncated,"truncated"},{Targets,"targets"},{Fingerprint,"fingerprint"},{Expires,"approvalExpiresAt"}};return row.value(keys.value(role)).toVariant();}
QJsonObject ApprovalModel::selected()const{for(const auto&value:rows_){const auto row=value.toObject();if(row.value("id")==selected_&&row.value("fingerprint")==fingerprint_&&row.value("conversationId")==scope_)return row;}return {};}
void ApprovalModel::clearDetails(){document_.invalidate();details_.clear();deadline_.clear();risk_.clear();expires_=0;emit detailsChanged();}
void ApprovalModel::invalidateReview(){clearDetails();emit changed();}
void ApprovalModel::setScope(const QString&cid){if(scope_==cid)return;scope_=cid;selected_.clear();fingerprint_.clear();clearDetails();emit changed();}
void ApprovalModel::setBlocked(bool blocked){if(blocked_==blocked)return;blocked_=blocked;if(blocked)clearDetails();emit changed();}
bool ApprovalModel::canDecide()const{return !blocked_&&!pending_&&selected().value("status")=="awaiting_approval"&&document_.canApprove()&&document_.manifest().value("operationId")==selected_&&document_.manifest().value("fingerprint")==fingerprint_&&expires_>QDateTime::currentMSecsSinceEpoch();}
void ApprovalModel::apply(const QJsonObject&snapshot){beginResetModel();rows_=snapshot.value("operations").toArray();status_=snapshot.value("status").toString();endResetModel();const auto current=selected();if(current.isEmpty()||current.value("status")!="awaiting_approval"||current.value("risk")!=risk_||current.value("approvalExpiresAt").toInteger()!=expires_){clearDetails();selected_.clear();fingerprint_.clear();}bool waiting=false;for(const auto&r:rows_)if(r.toObject().value("status")=="awaiting_approval")waiting=true;if(waiting)expiry_.start();else expiry_.stop();emit changed();}
bool ApprovalModel::select(const QString&id,const QString&fingerprint){clearDetails();selected_=id;fingerprint_=fingerprint;const auto row=selected();if(row.value("status")!="awaiting_approval"){selected_.clear();fingerprint_.clear();emit changed();return false;}risk_=row.value("risk").toString();expires_=row.value("approvalExpiresAt").toInteger();emit changed();return !blocked_&&expires_>QDateTime::currentMSecsSinceEpoch();}
void ApprovalModel::setDetails(const QJsonObject&){invalidateReview();}
bool ApprovalModel::setManifest(const QJsonObject&m){const auto row=selected();if(row.value("status")!="awaiting_approval"||m.value("conversationId")!=scope_||m.value("operationId")!=selected_||m.value("fingerprint")!=fingerprint_||m.value("risk")!=row.value("risk")||m.value("expiresAt")!=row.value("approvalExpiresAt"))return false;return document_.begin(m,scope_);}
bool ApprovalModel::acceptChunk(const QJsonObject&chunk){return document_.acceptChunk(chunk);}
void ApprovalModel::setDecisionPending(bool value){if(pending_==value)return;pending_=value;emit changed();}
void ApprovalModel::setDetailsDisplayed(bool value){document_.setDisplayed(value);}
